    /// Parses an expression atom.
    fn parse_expression_atom(&mut self) -> Result<ast::Expression> {
        match self.next()? {
            Some(Token::Asterisk) => Ok(ast::Expression::All),
            Token::Ident(s) => Ok(ast::Expression::Column(None, s)),
            Token::Keyword(k) => match k {
                Keyword::True => Ok(ast::Expression::Literal(ast::Literal::Boolean(true))),
                Keyword::False => Ok(ast::Expression::Literal(ast::Literal::Boolean(false))),
                Keyword::Null => Ok(ast::Expression::Literal(ast::Literal::Null)),
                Keyword::Infinity => Ok(ast::Expression::Literal(ast::Literal::Float(f64::INFINITY))),
                Keyword::NaN => Ok(ast::Expression::Literal(ast::Literal::Float(f64::NAN))),
                Keyword::Select | Keyword::From | Keyword::Where | Keyword::Group |
                Keyword::Having | Keyword::Order | Keyword::Limit | Keyword::Offset |
                Keyword::Join | Keyword::On | Keyword::And | Keyword::Or | Keyword::Not |
                Keyword::Begin | Keyword::Commit | Keyword::Rollback | Keyword::Explain |
                Keyword::Create | Keyword::Drop | Keyword::Delete | Keyword::Insert |
                Keyword::Update | Keyword::Values | Keyword::Into | Keyword::Set |
                Keyword::As | Keyword::Asc | Keyword::Desc | Keyword::By | Keyword::If |
                Keyword::Index | Keyword::Inner | Keyword::Left | Keyword::Outer |
                Keyword::Primary | Keyword::Read | Keyword::References | Keyword::Right |
                Keyword::String | Keyword::Table | Keyword::Text | Keyword::Time |
                Keyword::Transaction | Keyword::Unique | Keyword::Varchar | Keyword::Write |
                Keyword::Default | Keyword::Double | Keyword::Integer | Keyword::Int |
                Keyword::Float | Keyword::Boolean | Keyword::Bool | Keyword::Cross |
                Keyword::Of | Keyword::Only => {
                    Err(errinput!("unexpected keyword {k} in expression"))
                }
            },
            Token::Number(s) => {
                if s.contains('.') || s.contains('e') || s.contains('E') {
                    Ok(ast::Expression::Literal(ast::Literal::Float(s.parse().unwrap())))
                } else {
                    Ok(ast::Expression::Literal(ast::Literal::Integer(s.parse().unwrap())))
                }
            }
            Token::String(s) => Ok(ast::Expression::Literal(ast::Literal::String(s))),
            Some(Token::Minus) => {
                let expr = self.parse_expression_at(PrefixOperator::Minus.precedence())?;
                Ok(ast::Expression::Operator(ast::Operator::Negate(expr.into())))
            }
            Some(Token::Plus) => {
                let expr = self.parse_expression_at(PrefixOperator::Plus.precedence())?;
                Ok(ast::Expression::Operator(ast::Operator::Identity(expr.into())))
            }
            Token::OpenParen => {
                let expr = self.parse_expression()?;
                self.expect(Token::CloseParen)?;
                Ok(expr)
            }
            Token::Keyword(Keyword::Exists) => {
                self.expect(Token::OpenParen)?;
                let stmt = self.parse_statement()?;
                self.expect(Token::CloseParen)?;
                // EXISTS is handled by the planner, not the parser
                Ok(ast::Expression::Function("EXISTS".to_string(), vec![ast::Expression::All]))
            }
            Token::Period | Some(Token::Equal) | Some(Token::NotEqual) | Some(Token::GreaterThan) |
            Some(Token::GreaterThanOrEqual) | Some(Token::LessThan) | Some(Token::LessThanOrEqual) |
            Token::LessOrGreaterThan | Some(Token::Plus) | Some(Token::Slash) | Some(Token::Caret) |
            Some(Token::Percent) | Token::Exclamation | Token::Question | Token::Comma |
            Token::Semicolon | Token::CloseParen => {
                Err(errinput!("unexpected token in expression"))
            }
        }
    }

